// Prayers: generated by people from their circumstances and beliefs; resolved by the player or by the world.
// Response types: direct, indirect, delayed, silence, alternative.
(function (G) {
  'use strict';
  const S = G.Sim;
  const U = G.Util;
  const T = G.Time;
  const H = S.handlers;

  const URGENCY = ['', 'Low', 'Urgent', 'Critical'];
  S.URGENCY = URGENCY;
  const EXPIRY = [0, T.DAY * 4, T.DAY * 2, 14 * 60];
  const MAX_PENDING = 10;

  const sevOf = (c) => Math.max(c.illness ? c.illness.severity : 0, c.injury);
  const nearestBy = (world, c, filter) =>
    S.living(world).filter((o) => o.id !== c.id && filter(o)).sort((a, b) => U.dist(a.x, a.y, c.x, c.y) - U.dist(b.x, b.y, c.x, c.y))[0] || null;

  // Each template: urgency(world,c) -> 0..3, situation, plea, options, resolved(world,c), natural daily chance.
  const TEMPLATES = {
    health: {
      category: 'Health & healing', icon: '✚',
      urgency(world, c) {
        const v = sevOf(c);
        if (v < 18) return 0;
        return v >= 70 ? 3 : v >= 40 ? 2 : 1;
      },
      situation: (world, c) => (c.illness ? `${c.first} suffers from ${c.illness.name}.` : `${c.first} is badly injured.`),
      plea: (c) => (c.age < 14 ? `Please, make ${c.sex === 'f' ? 'her' : 'him'} well again.` : 'Spare me this sickness. I have people who need me.'),
      resolved: (world, c) => sevOf(c) < 12,
      natural: 0.25,
      direct: { ability: 'heal', target: 'self', label: 'Heal them', certainty: 'Certain', risk: 'Witnesses will talk; exposure rises.' },
      indirect: {
        label: 'Inspire a healer to tend them', cost: 25, certainty: 'Likely', risk: 'The healer, not you, may be credited. Can fail if the illness is grave.',
        run(world, p, c) {
          const healer = nearestBy(world, c, (o) => o.role === 'healer' || o.role === 'priest');
          if (!healer) return { ok: false, text: 'There is no one to send.' };
          const p0 = 0.85 - sevOf(c) / 200 + healer.traits.kindness * 0.1;
          S.schedule(world, 60 + world.rng.int(0, 120), 'indirect_heal', { cId: c.id, hId: healer.id, chance: p0, prayerId: p.id });
          S.addMemory(world, healer, 'inspired', `Felt urged to visit ${c.first}.`, 1);
          return { ok: true, text: `${healer.name} feels a sudden urge to visit ${c.first}.`, pending: true };
        },
      },
      delayed: {
        label: 'Grant a slow recovery', cost: 30, certainty: 'Probable over days', risk: 'They will suffer meanwhile, and may give up hope.',
        run(world, p, c) {
          S.schedule(world, T.DAY * world.rng.float(1, 3), 'delayed_heal', { cId: c.id, prayerId: p.id });
          return { ok: true, text: `${c.first}'s body has begun, slowly, to mend.`, pending: true };
        },
      },
      alternative: {
        label: 'Ease their suffering, not the illness', cost: 20, certainty: 'Certain (partial)', risk: 'The illness remains. They may find peace, or feel cheated.',
        run(world, p, c) {
          if (c.illness) c.illness.severity = Math.max(5, c.illness.severity * 0.6);
          c.injury *= 0.6;
          c.mood = U.clamp(c.mood + 20, 0, 100);
          S.adjustBelief(world, c, world.rng.chance(0.6) ? 4 : -2);
          S.addMemory(world, c, 'prayer', 'The pain eased after praying, though the sickness lingers.', 1.5);
          return { ok: true, text: `${c.first}'s pain eases; the illness lingers.` };
        },
      },
    },
    provision: {
      category: 'Food, shelter & livelihood', icon: '⚘',
      urgency(world, c) {
        if (c.role === 'child' || c.age < 15) return 0;
        const home = S.building(world, c.homeId);
        if (home && home.damage > 40) return 2;
        if (c.hunger > 75) return 3;
        if (c.hunger > 50 || c.wealth < 8) return 2;
        if (c.wealth < 10) return 1;
        return 0;
      },
      situation: (world, c) => {
        const home = S.building(world, c.homeId);
        if (home && home.damage > 40) return `The flood ruined the ${c.last} home.`;
        return c.hunger > 50 ? `The ${c.last} household is going hungry.` : `${c.first} cannot find enough work to pay the rent.`;
      },
      plea: () => 'Give us this day our bread. I am not asking for more.',
      resolved: (world, c) => c.hunger < 40 && c.wealth >= 15 && !((S.building(world, c.homeId) || {}).damage > 40),
      natural: 0.12,
      direct: { ability: 'provide', target: 'self', label: 'Provide for the household', certainty: 'Certain', risk: 'A visible miracle; neighbours may grow jealous.' },
      indirect: {
        label: 'Move a wealthy neighbour to help', cost: 25, certainty: 'Uncertain', risk: 'Depends on the generosity of the person you move.',
        run(world, p, c) {
          const rich = S.living(world).filter((o) => o.id !== c.id && o.wealth > 50 && o.age >= 18).sort((a, b) => b.traits.kindness - a.traits.kindness)[0];
          if (!rich) return { ok: false, text: 'No one has enough to share.' };
          const helps = world.rng.chance(0.25 + rich.traits.kindness * 0.7);
          if (helps) {
            rich.wealth -= 15;
            c.wealth = U.clamp(c.wealth + 30, 0, 100);
            c.hunger = 0;
            const home = S.building(world, c.homeId);
            if (home) home.damage = Math.max(0, home.damage - 40);
            S.relate(c, rich, 'friend', 75);
            rich.renown = U.clamp(rich.renown + 5, 0, 100);
            S.addMemory(world, c, 'help', `${rich.first} offered work and bread when it was most needed.`, 2);
            S.addMemory(world, rich, 'help', `Felt moved to help the ${c.last} household.`, 1);
            return { ok: true, text: `${rich.name} offered help to the ${c.last} household.`, resolved: true, credit: rich.belief > 50 ? 'divine' : 'human' };
          }
          S.addMemory(world, rich, 'inspired', `Felt a pang of conscience about the ${c.last} household, and ignored it.`, 1);
          return { ok: true, text: `${rich.name} felt the nudge, but kept their purse closed.`, resolved: false };
        },
      },
      delayed: {
        label: 'Open a door in the coming days', cost: 30, certainty: 'Probable', risk: 'They must hold on until it comes.',
        run(world, p, c) {
          S.schedule(world, T.DAY * world.rng.float(2, 4), 'delayed_fortune', { cId: c.id, prayerId: p.id });
          return { ok: true, text: 'An opportunity is on its way.', pending: true };
        },
      },
      alternative: {
        label: 'Fill their table, but not their purse', cost: 25, certainty: 'Certain (partial)', risk: 'Hunger returns if nothing else changes.',
        run(world, p, c) {
          for (const f of [c, ...S.familyOf(world, c)]) if (f.alive && f.homeId === c.homeId) f.hunger = 0;
          S.adjustBelief(world, c, 3);
          S.addMemory(world, c, 'prayer', 'There was bread enough for tonight.', 1);
          return { ok: true, text: 'The household eats tonight.' };
        },
      },
    },
    safety: {
      category: 'Safety in disaster or conflict', icon: '☂',
      urgency(world, c) {
        if (c.flags.trapped) return 3;
        if (S.isInFloodDanger(world, c)) return world.flood.stage === 'warning' ? 1 : 2;
        if (world.war && (c.role === 'soldier' || c.role === 'general')) return 1;
        return 0;
      },
      situation: (world, c) => (c.flags.trapped ? `${c.first} is trapped by floodwater at ${S.building(world, c.homeId)?.name || 'home'}.` : S.isInFloodDanger(world, c) ? `The flood is coming for ${c.first}'s home.` : `${c.first} fears for their life in the war.`),
      plea: (c) => (c.flags.trapped ? (c.age < 15 ? 'The water is coming in. Please, please help us.' : Object.values(c.relations).some((r) => r.type === 'child') ? 'The water is at the door. Please, save my children.' : 'The water is at the door. Please, save us.') : 'Keep us safe. Turn the water from our door.'),
      resolved: (world, c) => !c.flags.trapped && !S.isInFloodDanger(world, c) && !(world.war && (c.role === 'soldier' || c.role === 'general')),
      natural: 0.1,
      direct: { ability: 'protect', target: 'home', label: 'Ward their home', certainty: 'Certain', risk: 'The water parting around a single house will be seen and remembered.' },
      indirect: {
        label: 'Inspire an official to organise a rescue', cost: 60, certainty: 'Uncertain', risk: 'Human choices decide the outcome. The rescuer gains the glory.',
        run(world, p, c) {
          const off = [S.char(world, S.faction(world, 'military').leaderId), S.char(world, world.country.heirId), S.leader(world), ...S.living(world).filter((o) => o.role === 'official')].filter((o) => o && o.alive);
          const best = off.sort((a, b) => b.traits.kindness + b.traits.courage - (a.traits.kindness + a.traits.courage))[0];
          if (!best) return { ok: false, text: 'There is no one to inspire.' };
          if (world.flood.stage === 'none') return { ok: false, text: 'There is no flood to rescue them from.' };
          const willing = world.rng.chance(0.35 + best.traits.kindness * 0.35 + best.traits.courage * 0.25);
          S.addMemory(world, best, 'inspired', `Could not stop thinking about the families on the Riverside.`, 1);
          if (willing) {
            S.organizeRescue(world, best);
            return { ok: true, text: `${best.name} is organising a rescue.`, pending: true };
          }
          return { ok: true, text: `${best.name} hesitated, and did nothing.`, resolved: false };
        },
      },
      delayed: {
        label: 'Help them endure until morning', cost: 35, certainty: 'Probable', risk: 'They may be hurt in the long hours.',
        run(world, p, c) {
          for (const f of S.living(world).filter((o) => o.homeId === c.homeId)) f.flags.endure = world.t + T.DAY;
          S.schedule(world, 6 * 60, 'delayed_safety', { homeId: c.homeId, prayerId: p.id });
          return { ok: true, text: 'They will find a way to endure.', pending: true };
        },
      },
      alternative: {
        label: 'Divert the river elsewhere (regional miracle)', ability: 'regional', option: 'divert_river', certainty: 'Certain', risk: 'Saves the floodplain; the North Fields and the Upland Farm flood instead.',
      },
    },
    family: {
      category: 'Love, family & grief', icon: '♥',
      urgency(world, c) {
        if (c.flags.grief && world.t - c.flags.grief < T.DAY * 30) return c.mood < 30 ? 2 : 1;
        if (c.age >= 20 && c.age < 40 && !S.spouseOf(world, c) && c.mood < 50 && c.role !== 'priest') return 1;
        const estranged = Object.keys(c.relations).find((k) => ['parent', 'child', 'sibling'].includes(c.relations[k].type) && c.relations[k].affinity < 30);
        return estranged ? 1 : 0;
      },
      situation: (world, c) => {
        if (c.flags.grief) {
          const m = c.memories.slice().reverse().find((x) => x.kind === 'grief');
          return `${c.first} is grieving. ${m ? m.text : ''}`;
        }
        if (!S.spouseOf(world, c)) return `${c.first} is lonely and longs for a partner.`;
        return `${c.first} is estranged from family.`;
      },
      plea: (c) => (c.flags.grief ? 'Tell me they are at peace. Tell me why.' : 'Do not let me be alone.'),
      resolved: (world, c) => !c.flags.grief && c.mood > 50,
      natural: 0.12,
      direct: { ability: 'vision', option: 'comfort', target: 'self', label: 'Send a comforting vision', certainty: 'Likely', risk: 'Visions can be misunderstood.' },
      indirect: {
        label: 'Move a friend to visit', cost: 15, certainty: 'Likely', risk: 'A friend can comfort, but cannot replace the lost.',
        run(world, p, c) {
          const fid = Object.keys(c.relations).find((k) => c.relations[k].type === 'friend' && S.char(world, +k)?.alive);
          const f = S.char(world, +fid);
          if (!f) return { ok: false, text: `${c.first} has no friends to send.` };
          c.mood = U.clamp(c.mood + 18, 0, 100);
          c.relations[f.id].affinity = U.clamp(c.relations[f.id].affinity + 10, 0, 100);
          S.goTo(world, f, c.homeId, `visiting ${c.first}`);
          S.addMemory(world, c, 'comfort', `${f.first} came by when it mattered.`, 1.5);
          return { ok: true, text: `${f.name} went to sit with ${c.first}.`, resolved: c.mood > 50 || world.rng.chance(0.5), credit: 'human' };
        },
      },
      delayed: {
        label: 'Arrange a chance meeting', cost: 25, certainty: 'Uncertain', risk: 'Love cannot be commanded.',
        run(world, p, c) {
          S.schedule(world, T.DAY * world.rng.float(2, 7), 'delayed_meeting', { cId: c.id, prayerId: p.id });
          return { ok: true, text: 'Paths will cross.', pending: true };
        },
      },
      alternative: {
        label: 'Grant acceptance rather than answers', cost: 15, certainty: 'Certain (partial)', risk: 'They may stop asking, and stop praying.',
        run(world, p, c) {
          c.mood = U.clamp(c.mood + 12, 0, 100);
          if (c.flags.grief) c.flags.grief = world.t - T.DAY * 25;
          S.adjustBelief(world, c, -1);
          S.addMemory(world, c, 'prayer', 'Found a quiet acceptance.', 1);
          return { ok: true, text: `${c.first} finds a quiet acceptance.`, resolved: true };
        },
      },
    },
    justice: {
      category: 'Justice, freedom & political change', icon: '⚖',
      urgency(world, c) {
        if (c.flags.detainedUntil > world.t) return 2;
        const country = world.country;
        if ((c.factionId === 'reformers' || c.factionId === 'commons') && c.age >= 18 && country.corruption > 50 && country.legitimacy < 45 && c.belief > 25 && world.rng.chance(0.02)) return 1;
        return 0;
      },
      situation: (world, c) => (c.flags.detainedUntil > world.t ? `${c.first} languishes in the gaol.` : `${c.first} is outraged by corruption at court.`),
      plea: (c) => (c.flags.detainedUntil ? 'I have done nothing but speak the truth. Set me free.' : 'How long will the wicked prosper? Show them for what they are.'),
      resolved: (world, c) => !(c.flags.detainedUntil > world.t) && world.country.corruption < 40,
      natural: 0.05,
      direct: {
        ability: 'reveal', target: 'corrupt', label: 'Reveal the wrongdoing of a corrupt official', certainty: 'Certain', risk: 'The Crown loses face; the Reformers grow bolder.',
      },
      indirect: {
        label: 'Inspire the Reformers\' leader', cost: 50, certainty: 'Uncertain', risk: 'Reform may become revolution.',
        run(world, p, c) {
          const ref = S.char(world, S.faction(world, 'reformers').leaderId);
          if (!ref || !ref.alive) return { ok: false, text: 'The Reformers have no leader.' };
          S.faction(world, 'reformers').power = U.clamp(S.faction(world, 'reformers').power + 5, 0, 100);
          world.country.reformPressure = U.clamp(world.country.reformPressure + 7, 0, 100);
          ref.renown = U.clamp(ref.renown + 6, 0, 100);
          S.addMemory(world, ref, 'inspired', 'Wrote the most stirring pamphlet of their life in a single night.', 2);
          if (c.flags.detainedUntil > world.t && world.rng.chance(0.4)) {
            c.flags.detainedUntil = world.t + 60;
            return { ok: true, text: `${ref.name}'s pamphlets shamed the court into releasing ${c.first}.`, resolved: true, credit: 'human' };
          }
          return { ok: true, text: `${ref.name}'s new pamphlet is the talk of the taverns.`, resolved: false };
        },
      },
      delayed: {
        label: 'Sow the seeds of change', cost: 40, certainty: 'Slow', risk: 'Change may come too late for them.',
        run(world, p, c) {
          for (let i = 1; i <= 5; i++) S.schedule(world, T.DAY * i * 2, 'reform_seed', {});
          return { ok: true, text: 'Discontent with corruption will grow.', resolved: false };
        },
      },
      alternative: {
        label: 'A small mercy: soften their jailers', cost: 30, certainty: 'Likely', risk: 'Nothing changes at court.',
        run(world, p, c) {
          if (c.flags.detainedUntil > world.t) {
            c.flags.detainedUntil = world.t + 60;
            S.addMemory(world, c, 'prayer', 'The guard left the door unlocked. Walked free.', 2);
            S.adjustBelief(world, c, 6);
            return { ok: true, text: `${c.first} walks free.`, resolved: true };
          }
          c.mood = U.clamp(c.mood + 10, 0, 100);
          return { ok: true, text: `${c.first} feels heard.`, resolved: true };
        },
      },
    },
    guidance: {
      category: 'Guidance & spiritual understanding', icon: '✦',
      urgency(world, c) {
        if (c.age < 14) return 0;
        const recentMiracle = c.memories.find((m) => (m.kind === 'miracle' || m.kind === 'gift' || m.kind === 'possessed') && world.t - m.t < T.DAY * 4);
        if (recentMiracle && c.belief > 20) return 1;
        if (c.belief > 30 && c.belief < 80 && world.rng.chance(0.012)) return 1;
        return 0;
      },
      situation: (world, c) => {
        const m = c.memories.slice().reverse().find((x) => x.kind === 'miracle' || x.kind === 'gift' || x.kind === 'possessed');
        return m && world.t - m.t < T.DAY * 4 ? `${c.first} is shaken by what happened and seeks meaning.` : `${c.first} stands at a crossroads and asks what to do.`;
      },
      plea: () => 'What do you want of me? Show me the way.',
      resolved: () => false,
      natural: 0.3,
      direct: { ability: 'vision', option: 'guidance', target: 'self', label: 'Send a vision of guidance', certainty: 'Likely', risk: 'They will act on what they think you meant.' },
      indirect: {
        label: 'Send a priest to counsel them', cost: 12, certainty: 'Likely', risk: 'The priest will teach the Church\'s interpretation, not yours.',
        run(world, p, c) {
          const pr = nearestBy(world, c, (o) => o.role === 'priest');
          if (!pr) return { ok: false, text: 'There is no priest.' };
          S.adjustBelief(world, c, 4);
          if (!c.movementId && world.rng.chance(0.4)) c.interpretation = world.church.doctrine;
          S.addMemory(world, c, 'counsel', `${pr.first} offered counsel.`, 1);
          return { ok: true, text: `${pr.name} counselled ${c.first}.`, resolved: true, credit: 'church' };
        },
      },
      delayed: {
        label: 'Promise a sign to come', cost: 10, certainty: 'Probable', risk: 'They may read meaning into anything.',
        run(world, p, c) {
          S.schedule(world, T.DAY * world.rng.float(1, 3), 'delayed_sign', { cId: c.id, prayerId: p.id });
          return { ok: true, text: 'A sign will come.', pending: true };
        },
      },
      alternative: { label: 'Send an ambiguous sign', ability: 'subtle_sign', target: 'self', certainty: 'Ambiguous', risk: 'They may find no meaning in it at all.' },
    },
    victory: {
      category: 'Military victory & protection from invasion', icon: '⚔',
      urgency(world, c) {
        if (!world.war) return 0;
        if (c.id === world.country.leaderId || c.role === 'general') return 3;
        if (c.role === 'soldier') return 2;
        return 0;
      },
      situation: (world) => `${S.neighbor(world, world.war.enemy).name} armies hold ground in the Highmarch.`,
      plea: () => 'Give our arms strength. Drive them from our land.',
      resolved: (world) => !world.war,
      natural: 0.02,
      direct: { ability: 'regional', option: 'storm_on_enemy', target: 'province:highmarch', label: 'Storm upon the invader', certainty: 'Strong effect', risk: 'A massive, public miracle. The enemy will hate you too.' },
      indirect: {
        label: 'Inspire the general', cost: 150, certainty: 'Uncertain', risk: 'Courage is not always wisdom.',
        run(world) {
          if (!world.war) return { ok: false, text: 'There is no war.' };
          const gen = S.char(world, S.faction(world, 'military').leaderId);
          const good = world.rng.chance(0.55 + (gen ? gen.traits.courage * 0.3 : 0));
          world.war.score = U.clamp(world.war.score + (good ? 15 : -5), -100, 100);
          return { ok: true, text: good ? `${gen ? gen.name : 'The general'} led a bold charge that broke the enemy line.` : `${gen ? gen.name : 'The general'} charged recklessly and lost men.`, resolved: false };
        },
      },
      delayed: {
        label: 'Turn the tide over the coming weeks', cost: 300, certainty: 'Gradual', risk: 'Many will die before the tide turns.',
        run(world) {
          if (!world.war) return { ok: false, text: 'There is no war.' };
          world.war.tide = 1.5;
          return { ok: true, text: 'Fortune will slowly favour Velmora.', resolved: false };
        },
      },
      alternative: {
        label: 'Shield the soldiers, not the cause', cost: 200, certainty: 'Certain', risk: 'The war goes on; pressure for peace grows.',
        run(world) {
          if (!world.war) return { ok: false, text: 'There is no war.' };
          world.war.shield = world.t + T.DAY * 30;
          world.country.warRisk = U.clamp(world.country.warRisk - 10, 0, 100);
          if (world.rng.chance(0.3)) S.endWar(world, 'peace', 'With few dead on either side, envoys found it easy to agree a truce.');
          return { ok: true, text: 'The soldiers are shielded.', resolved: !world.war };
        },
      },
    },
    discovery: {
      category: 'Discovery & hopes for the future', icon: '☉',
      urgency(world, c) {
        if ((c.role === 'scholar' || c.role === 'student') && world.rng.chance(0.03)) return 1;
        return 0;
      },
      situation: (world, c) => `${c.first} is stuck on a problem in natural philosophy and hopes for a breakthrough.`,
      plea: (c) => (c.belief < 25 ? 'If anyone is listening, which I doubt: let me understand.' : 'Open my eyes to how the world is made.'),
      resolved: () => false,
      natural: 0.15,
      direct: { ability: 'vision', option: 'insight', target: 'self', label: 'Grant an insight', certainty: 'Likely', risk: 'A skeptic will credit their own genius.' },
      indirect: {
        label: 'Kindle curiosity in a student', cost: 20, certainty: 'Uncertain', risk: 'Slow, and someone else gets the credit.',
        run(world) {
          world.country.literacy = U.clamp(world.country.literacy + 1, 0, 100);
          if (world.rng.chance(0.5)) world.country.technology = U.clamp(world.country.technology + 1.5, 0, 100);
          return { ok: true, text: 'A student at the Academy finds new passion for learning.', resolved: true, credit: 'human' };
        },
      },
      delayed: {
        label: 'Plant an idea to bloom later', cost: 25, certainty: 'Probable', risk: 'It may bloom in someone else\'s mind.',
        run(world, p, c) {
          S.schedule(world, T.DAY * world.rng.float(3, 7), 'delayed_insight', { cId: c.id, prayerId: p.id });
          return { ok: true, text: 'An idea will grow.', pending: true };
        },
      },
      alternative: null,
    },
  };
  S.PRAYER_TEMPLATES = TEMPLATES;

  // ---------- generation ----------
  S.generatePrayers = function (world) {
    const rng = world.rng;
    const pending = world.prayers.filter((p) => p.status === 'pending');
    if (pending.length >= MAX_PENDING) return;
    const pendingBy = new Set(pending.map((p) => p.requesterId));
    for (const c of S.living(world)) {
      if (c.asleep || c.possessed || pendingBy.has(c.id) || world.t < c.prayerCooldownUntil) continue;
      if (c.belief < 8 && !c.flags.trapped) continue;
      let best = null;
      for (const id in TEMPLATES) {
        const u = TEMPLATES[id].urgency(world, c);
        if (u > 0 && (!best || u > best.u)) best = { id, u };
      }
      if (!best) continue;
      // Desperation overrides doubt; devout people pray more often.
      const p = (0.005 + (c.belief / 100) * 0.018 + c.traits.piety * 0.008) * (best.u === 3 ? 12 : best.u === 2 ? 3 : 1);
      if (!rng.chance(p)) continue;
      S.createPrayer(world, c, best.id, best.u);
      pendingBy.add(c.id);
      if (world.prayers.filter((x) => x.status === 'pending').length >= MAX_PENDING) break;
    }
  };

  S.createPrayer = function (world, c, typeId, urgency) {
    const tpl = TEMPLATES[typeId];
    const p = {
      id: world.nextId++, typeId, category: tpl.category, icon: tpl.icon, requesterId: c.id, requesterName: c.name,
      location: { x: c.x, y: c.y, district: S.districtAt(world, c.x, c.y), place: (S.building(world, c.at) || {}).name || S.districtName(S.districtAt(world, c.x, c.y)) },
      situation: tpl.situation(world, c), plea: tpl.plea(c), urgency, createdAt: world.t, expiresAt: world.t + EXPIRY[urgency],
      status: 'pending', response: null, outcome: null, beliefAtTime: Math.round(c.belief),
      memories: c.memories.slice(-3).map((m) => m.text), history: Object.assign({}, c.divine),
    };
    world.prayers.push(p);
    c.prayerCooldownUntil = world.t + T.DAY * (urgency >= 3 ? 0.25 : 3);
    if (world.prayers.length > 400) world.prayers = world.prayers.filter((x) => x.status === 'pending' || world.t - x.createdAt < T.DAY * 60);
    if (urgency >= 3) S.log(world, { title: 'A desperate prayer', text: `${c.name}: "${p.plea}"`, level: 1, kind: 'prayer', entities: [c.id] });
    return p;
  };

  // ---------- options shown on a prayer card ----------
  S.resolveTargetRef = function (world, p, spec) {
    const c = S.char(world, p.requesterId);
    if (!spec.target || spec.target === 'self') return { kind: 'character', id: c.id };
    if (spec.target === 'home') return { kind: 'building', id: c.homeId };
    if (spec.target === 'corrupt') {
      const off = S.living(world).find((o) => o.corrupt);
      return off ? { kind: 'character', id: off.id } : null;
    }
    if (spec.target.startsWith('province:')) return { kind: 'province', id: spec.target.split(':')[1] };
    return null;
  };

  S.prayerOptions = function (world, p) {
    const tpl = TEMPLATES[p.typeId];
    const c = S.char(world, p.requesterId);
    if (!tpl || !c) return [];
    const out = [];
    const abilityOption = (kind, spec) => {
      const ref = S.resolveTargetRef(world, p, spec);
      let target = null;
      if (ref) target = ref.kind === 'character' ? S.char(world, ref.id) : ref.kind === 'building' ? S.building(world, ref.id) : S.province(world, ref.id);
      const check = ref ? S.canUseAbility(world, spec.ability, target, spec.option) : { ok: false, reason: 'No valid target' };
      const cost = ref ? S.abilityCost(world, spec.ability, target, spec.option) : 0;
      out.push({ kind, label: spec.label || G.Data.abilities[spec.ability].name, cost, certainty: spec.certainty, risk: spec.risk, available: check.ok, reason: check.ok ? '' : check.reason });
    };
    abilityOption('direct', tpl.direct);
    for (const kind of ['indirect', 'delayed', 'alternative']) {
      const spec = tpl[kind];
      if (!spec) continue;
      if (spec.ability) {
        abilityOption(kind, spec);
        continue;
      }
      const cost = Math.round(spec.cost * (world.settings.costMultiplier || 1));
      let available = world.player.form !== 'human' && world.faith.current >= cost;
      let reason = world.player.form === 'human' ? 'No divine abilities in human form' : available ? '' : `Not enough Faith (${cost})`;
      out.push({ kind, label: spec.label, cost, certainty: spec.certainty, risk: spec.risk, available, reason });
    }
    out.push({ kind: 'silence', label: 'Remain silent', cost: 0, certainty: 'The world decides', risk: 'They will interpret your silence for themselves.', available: true, reason: '' });
    return out;
  };

  // ---------- responding ----------
  S.respondPrayer = function (world, prayerId, kind) {
    const p = world.prayers.find((x) => x.id === prayerId);
    if (!p || p.status !== 'pending') return { ok: false, msg: 'That prayer is no longer pending.' };
    const tpl = TEMPLATES[p.typeId];
    const c = S.char(world, p.requesterId);
    if (!c || !c.alive) {
      p.status = 'void';
      return { ok: false, msg: 'They are gone.' };
    }
    if (kind === 'silence') {
      p.status = 'ignored';
      p.response = 'silence';
      world.stats.ignored++;
      S.schedule(world, Math.max(60, p.expiresAt - world.t), 'silence_outcome', { prayerId: p.id });
      S.log(world, { title: 'You remained silent', text: `You did not answer ${c.name}. The world will take its course.`, level: 0, kind: 'prayer', entities: [c.id] });
      return { ok: true, msg: 'You remain silent.' };
    }
    const spec = tpl[kind];
    if (!spec) return { ok: false, msg: 'Not possible.' };
    if (world.player.form === 'human') return { ok: false, msg: 'No divine abilities in human form.' };
    if (spec.ability) {
      const ref = S.resolveTargetRef(world, p, spec);
      if (!ref) return { ok: false, msg: 'No valid target.' };
      p.respondingWith = kind;
      const r = S.useAbility(world, spec.ability, ref, spec.option);
      p.respondingWith = null;
      if (!r.ok) return r;
      if (p.status === 'pending') {
        // The ability did not by itself satisfy the prayer (e.g. ambiguous sign)
        markAnswered(world, p, kind, r.msg, false);
      }
      return r;
    }
    const cost = Math.round(spec.cost * (world.settings.costMultiplier || 1));
    if (!S.spendFaith(world, cost, spec.label)) return { ok: false, msg: `Not enough Faith (${cost}).` };
    const r = spec.run(world, p, c);
    if (!r.ok) {
      world.faith.current += cost; // refund
      world.faith.spent -= cost;
      return { ok: false, msg: r.text };
    }
    p.response = kind;
    p.outcome = r.text;
    if (r.pending) p.status = 'answered';
    else markAnswered(world, p, kind, r.text, r.resolved !== false, r.credit);
    if (r.pending) {
      world.stats.answered++;
      c.divine.answered++;
    }
    S.log(world, { title: `${kindLabel(kind)} answer`, text: `${c.name}'s prayer: ${r.text}`, level: 1, kind: 'prayer', entities: [c.id], cost });
    S.recomputeFaithRates(world);
    return { ok: true, msg: r.text, cost };
  };

  function kindLabel(k) {
    return { direct: 'Direct', indirect: 'Indirect', delayed: 'Delayed', alternative: 'Alternative', silence: 'Silent' }[k] || k;
  }

  function markAnswered(world, p, kind, text, satisfied, credit) {
    const c = S.char(world, p.requesterId);
    p.status = 'answered';
    p.response = kind;
    p.outcome = text;
    world.stats.answered++;
    if (!c) return;
    c.divine.answered++;
    if (satisfied) {
      // Who gets the credit shapes belief.
      if (credit === 'human') S.adjustBelief(world, c, c.belief > 50 ? 3 : 0.5);
      else if (credit === 'church') world.church.strength = U.clamp(world.church.strength + 0.5, 0, 100);
      else S.adjustBelief(world, c, 6);
      S.addMemory(world, c, 'prayer', `Prayed (${p.category.toLowerCase()}) and was answered.`, 2);
      S.addGratitude(world, c, 18);
      // Communities come to expect protection.
      world.reputation[p.location.district] && (world.reputation[p.location.district].expectation = (world.reputation[p.location.district].expectation || 0) + 1);
    }
  }

  // Abilities used directly (not via a card) can still satisfy pending prayers.
  S.prayersAfterAbility = function (world, abilityId, target, option, kind) {
    for (const p of world.prayers) {
      if (p.status !== 'pending') continue;
      const tpl = TEMPLATES[p.typeId];
      const c = S.char(world, p.requesterId);
      if (!c) continue;
      let hit = false;
      if (kind === 'character' && target && target.id === c.id) {
        if (tpl.direct.ability === abilityId && (!tpl.direct.option || tpl.direct.option === option)) hit = true;
        if (tpl.alternative && tpl.alternative.ability === abilityId) hit = true;
      }
      if (kind === 'building' && target && abilityId === 'protect' && (c.homeId === target.id || c.at === target.id) && p.typeId === 'safety') hit = true;
      if (abilityId === 'regional' && (option === 'calm_waters' || option === 'divert_river') && p.typeId === 'safety' && tpl.resolved(world, c)) hit = true;
      if (abilityId === 'regional' && option === 'cleanse_plague' && p.typeId === 'health' && tpl.resolved(world, c)) hit = true;
      if ((abilityId === 'national' && option === 'forge_peace') || (abilityId === 'regional' && option === 'storm_on_enemy')) if (p.typeId === 'victory') hit = true;
      if (abilityId === 'reveal' && p.typeId === 'justice') hit = true;
      if (abilityId === 'regional' && option === 'bountiful_harvest' && p.typeId === 'provision') hit = true;
      if (hit) markAnswered(world, p, p.respondingWith || 'direct', 'Answered by your miracle.', true);
    }
  };

  // ---------- hourly upkeep: natural resolution and expiry ----------
  S.prayersHourly = function (world) {
    const rng = world.rng;
    for (const p of world.prayers) {
      if (p.status !== 'pending') continue;
      const c = S.char(world, p.requesterId);
      const tpl = TEMPLATES[p.typeId];
      if (!c || !c.alive) {
        p.status = 'void';
        continue;
      }
      if (tpl.resolved(world, c) && world.t - p.createdAt > 60) {
        p.status = 'resolved';
        p.outcome = 'Resolved without divine help.';
        world.stats.natural++;
        naturalInterpretation(world, c, p);
        continue;
      }
      if (world.t >= p.expiresAt) {
        if (rng.chance(tpl.natural)) {
          p.status = 'resolved';
          p.outcome = 'Things worked out on their own.';
          world.stats.natural++;
          naturalInterpretation(world, c, p);
        } else {
          p.status = 'unanswered';
          p.outcome = 'No answer came.';
          world.stats.unanswered++;
          disappointment(world, c, p);
        }
      }
    }
  };

  function naturalInterpretation(world, c, p) {
    // Believers may credit the divine anyway; skeptics credit themselves.
    if (c.belief > 50) {
      S.adjustBelief(world, c, 2);
      S.addMemory(world, c, 'prayer', `Prayed for help (${p.category.toLowerCase()}); things improved, and they believe heaven listened.`, 1);
    } else S.addMemory(world, c, 'prayer', `Prayed for help (${p.category.toLowerCase()}); things improved on their own.`, 0.8);
  }

  function disappointment(world, c, p) {
    const rng = world.rng;
    c.divine.unanswered++;
    const district = p.location.district;
    const expectation = (world.reputation[district] && world.reputation[district].expectation) || 0;
    // Expectations raised by past miracles make silence hurt more.
    const base = 2 + p.urgency * 1.5 + Math.min(6, expectation * 0.8);
    const r = rng.next();
    let text;
    if (c.traits.piety > 0.6 && r < 0.5) {
      text = 'No answer came. Decided it must be part of a greater plan.';
      S.adjustBelief(world, c, -base * 0.2);
    } else if (r < 0.7) {
      text = 'No answer came. Doubt is creeping in.';
      S.adjustBelief(world, c, -base);
    } else {
      text = 'No answer came. Is angry at heaven.';
      S.adjustBelief(world, c, -base * 1.4);
      c.mood = U.clamp(c.mood - 8, 0, 100);
    }
    S.addMemory(world, c, 'prayer', text, 1.5);
    if (p.urgency >= 3) S.log(world, { title: 'An unanswered prayer', text: `${c.name}'s desperate prayer went unanswered. ${text.replace('No answer came. ', '')}`, level: 1, kind: 'prayer', entities: [c.id] });
  }

  H.silence_outcome = function (world, data) {
    const p = world.prayers.find((x) => x.id === data.prayerId);
    if (!p) return;
    const c = S.char(world, p.requesterId);
    if (!c || !c.alive) return;
    const tpl = TEMPLATES[p.typeId];
    if (tpl.resolved(world, c) || world.rng.chance(tpl.natural)) {
      p.outcome = 'Resolved without divine help.';
      naturalInterpretation(world, c, p);
    } else {
      p.outcome = 'Silence. No help came.';
      disappointment(world, c, p);
    }
  };

  // ---------- delayed / indirect resolutions ----------
  const findP = (world, id) => world.prayers.find((x) => x.id === id);
  function finish(world, prayerId, c, text, good) {
    const p = findP(world, prayerId);
    if (p) p.outcome = text;
    if (c && good) {
      S.adjustBelief(world, c, 5);
      S.addGratitude(world, c, 12);
    }
    S.log(world, { title: good ? 'A prayer fulfilled' : 'A prayer falls short', text, level: 1, kind: 'prayer', entities: c ? [c.id] : [] });
  }
  H.indirect_heal = function (world, d) {
    const c = S.char(world, d.cId);
    const h = S.char(world, d.hId);
    if (!c || !c.alive || !h || !h.alive) return;
    S.goTo(world, h, c.homeId, `tending ${c.first}`);
    if (world.rng.chance(d.chance)) {
      if (c.illness) c.illness.severity = Math.max(0, c.illness.severity - 50);
      if (c.illness && c.illness.severity < 10) c.illness = null;
      c.injury = Math.max(0, c.injury - 40);
      h.renown = U.clamp(h.renown + 6, 0, 100);
      S.relate(c, h, 'friend', 80);
      S.addMemory(world, c, 'help', `${h.first} came and tended to them.`, 2);
      finish(world, d.prayerId, c, `${h.name} tended ${c.first}, who is recovering. Some say ${h.first} has a healing touch.`, true);
    } else finish(world, d.prayerId, c, `${h.name} tended ${c.first}, but could not turn the illness.`, false);
  };
  H.delayed_heal = function (world, d) {
    const c = S.char(world, d.cId);
    if (!c || !c.alive) return;
    if (world.rng.chance(0.85)) {
      c.illness = null;
      c.injury = 0;
      c.health = Math.max(c.health, 70);
      S.addMemory(world, c, 'prayer', 'Recovered, slowly, as if someone had answered.', 2);
      finish(world, d.prayerId, c, `${c.name} has recovered.`, true);
    } else finish(world, d.prayerId, c, `${c.name}'s recovery stalled.`, false);
  };
  H.delayed_fortune = function (world, d) {
    const c = S.char(world, d.cId);
    if (!c || !c.alive) return;
    c.wealth = U.clamp(c.wealth + 35, 0, 100);
    c.hunger = 0;
    const home = S.building(world, c.homeId);
    if (home) home.damage = Math.max(0, home.damage - 50);
    S.addMemory(world, c, 'prayer', 'Was offered steady work out of nowhere.', 2);
    finish(world, d.prayerId, c, `${c.name} found steady work.`, true);
  };
  H.delayed_meeting = function (world, d) {
    const c = S.char(world, d.cId);
    if (!c || !c.alive) return;
    if (c.flags.grief) {
      c.flags.grief = 0;
      c.mood = U.clamp(c.mood + 20, 0, 100);
      return finish(world, d.prayerId, c, `${c.name} met someone who had lost what they had lost. They talked until dawn.`, true);
    }
    const cand = S.living(world).find((o) => o.id !== c.id && o.sex !== c.sex && o.age >= 18 && Math.abs(o.age - c.age) < 12 && !S.spouseOf(world, o) && !c.relations[o.id]);
    if (cand && world.rng.chance(0.75)) {
      S.relate(c, cand, 'friend', 70);
      S.relate(cand, c, 'friend', 70);
      c.mood = U.clamp(c.mood + 20, 0, 100);
      S.addMemory(world, c, 'love', `Met ${cand.first} by chance at the market.`, 2);
      finish(world, d.prayerId, c, `${c.name} met ${cand.name} by chance. Something has begun.`, true);
    } else finish(world, d.prayerId, c, `${c.name}'s paths crossed no one's.`, false);
  };
  H.delayed_safety = function (world, d) {
    const fam = S.living(world).filter((o) => o.homeId === d.homeId && o.flags.trapped);
    for (const c of fam) {
      if (world.rng.chance(0.65)) {
        c.flags.trapped = false;
        c.flags.evacuating = true;
        S.addMemory(world, c, 'survival', 'Found a way across the water at first light.', 2);
      }
    }
    const c = fam[0];
    finish(world, d.prayerId, c, fam.length ? `The trapped household found a way out at first light.` : 'They were already safe.', true);
  };
  H.delayed_sign = function (world, d) {
    const c = S.char(world, d.cId);
    if (!c || !c.alive) return;
    S.adjustBelief(world, c, 6);
    S.addMemory(world, c, 'sign', 'Received the sign they had prayed for.', 2);
    finish(world, d.prayerId, c, `${c.name} received a sign.`, true);
  };
  H.delayed_insight = function (world, d) {
    const c = S.char(world, d.cId);
    if (!c || !c.alive) return;
    if (world.rng.chance(0.7)) {
      S.EFFECTS.vision(world, c, 'insight');
      finish(world, d.prayerId, c, `${c.name}'s idea bloomed.`, true);
    } else finish(world, d.prayerId, c, `${c.name}'s idea came to nothing.`, false);
  };
  H.reform_seed = function (world) {
    world.country.reformPressure = U.clamp(world.country.reformPressure + 2, 0, 100);
    world.country.corruption = U.clamp(world.country.corruption - 1, 0, 100);
  };
})((globalThis.GODSIM = globalThis.GODSIM || {}));
